<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { Layers3, ArrowUpRight, Users, Sparkles, Plus, LogOut, Settings2, BookOpen, ArrowLeft, Check, RefreshCw, Pencil, Trash2, ShieldCheck, ChevronRight, CalendarDays, CalendarRange, Paperclip, AlertTriangle, Compass } from 'lucide-vue-next';
import EditDialog, { type Field } from './components/EditDialog.vue';
import { api, apiForm, login, streamPlan } from './api';
type Row=Record<string,any>;
const window=globalThis.window;
const user=ref<Row|null>(null),username=ref('admin'),password=ref(''),loginError=ref(''),loading=ref(true),busy=ref(false),notice=ref(''),error=ref('');
const tab=ref('projects'),projects=ref<Row[]>([]),employees=ref<Row[]>([]),skills=ref<Row[]>([]),departments=ref<Row[]>([]),categories=ref<Row[]>([]),accounts=ref<Row[]>([]),mode=ref('off');
const selected=ref<Row|null>(null),tasks=ref<Row[]>([]),milestones=ref<Row[]>([]),task=ref<Row|null>(null),needs=ref<Row[]>([]),dependencies=ref<Row[]>([]),candidateRows=ref<Row[]>([]),plans=ref<Row[]>([]),plan=ref<Row|null>(null),draft=ref<Row|null>(null),review=ref(''),progress=ref(''),timeline=ref<Row|null>(null),strategy=ref('BALANCED'),compareWith=ref(''),compare=ref<Row|null>(null),impact=ref<Row|null>(null);
const employee=ref<Row|null>(null),employeeSkills=ref<Row[]>([]),availability=ref<Row[]>([]),search=ref(''),skillText=ref(''),skillDraft=ref<Row|null>(null),evidence=ref<Row[]>([]),alerts=ref<Row[]>([]),notify=ref<Row|null>(null),notifyLog=ref<Row[]>([]),supplyDemand=ref<Row|null>(null),keyPeople=ref<Row[]>([]),sdWeeks=ref(12),leavePick=ref(''),leaveImpact=ref<Row|null>(null),adviseText=ref(''),scenario=ref<Row|null>(null),trends=ref<Row|null>(null),semantic=ref<Row|null>(null),semanticQuery=ref('');
const dialog=ref<{title:string;fields:Field[];initial:Row;save:(v:Row)=>Promise<void>}|null>(null);
const admin=computed(()=>user.value?.roles.includes('ADMIN'));
const canPeople=computed(()=>admin.value||user.value?.roles.includes('DEPARTMENT_MANAGER'));
const canPlan=computed(()=>admin.value||user.value?.roles.includes('PROJECT_MANAGER'));
const filteredEmployees=computed(()=>employees.value.filter(e=>(e.name+e.employeeNo).toLowerCase().includes(search.value.toLowerCase())));
const nameOf=(list:Row[],id:any)=>list.find(r=>r.id===id)?.name||'—';
const options=(rows:Row[])=>rows.map(r=>({value:r.id,label:r.name}));
const dateField=(key:string,label:string):Field=>({key,label,type:'date',required:true});
const textField=(key:string,label:string,required=true):Field=>({key,label,required});
const selectField=(key:string,label:string,rows:Row[],required=true):Field=>({key,label,type:'select',options:options(rows),required});
async function run(action:()=>Promise<void>,message=''){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();notice.value=message;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function all(path:string){let list:Row[]=[];for(let page=1;;page++){const p=await api(`${path}?pageSize=200&pageNum=${page}`);list.push(...p.list);if(list.length>=p.total||!p.list.length)return list;}}
async function refresh(){[projects.value,employees.value,skills.value,departments.value,categories.value]=await Promise.all([all('/projects'),all('/employees'),all('/skills'),api('/departments'),api('/skill-categories')]);mode.value=(await api('/ai/status')).mode;alerts.value=await api('/replan/alerts');if(admin.value)accounts.value=await api('/auth/users');}
async function signIn(){loginError.value='';busy.value=true;try{await login(username.value,password.value);password.value='';user.value=await api('/auth/me');await refresh();}catch(e){loginError.value=(e as Error).message;}finally{busy.value=false;}}
async function signOut(){await api('/auth/logout','POST');user.value=null;selected.value=null;employee.value=null;}
onMounted(async()=>{window.addEventListener('session-expired',()=>{user.value=null;});try{user.value=await api('/auth/me');await refresh();}catch{}finally{loading.value=false;}});
async function openProject(p:Row){selected.value=p;draft.value=null;plan.value=null;review.value='';task.value=null;candidateRows.value=[];impact.value=null;await reloadProject();}
async function reloadProject(){if(!selected.value)return;const id=selected.value.id;[tasks.value,milestones.value,plans.value]=await Promise.all([api(`/projects/${id}/tasks`),api(`/projects/${id}/milestones`),api(`/projects/${id}/resource-plans`)]);}
async function openTask(t:Row){task.value=t;[needs.value,dependencies.value]=await Promise.all([api(`/tasks/${t.id}/skill-requirements`),api(`/tasks/${t.id}/dependencies`)]);}
async function openEmployee(e:Row){employee.value=e;skillDraft.value=null;[employeeSkills.value,availability.value,evidence.value]=await Promise.all([api(`/employees/${e.id}/skills`),api(`/employees/${e.id}/availability`),api(`/employees/${e.id}/skills/evidence`)]);}
function edit(title:string,fields:Field[],initial:Row,save:(v:Row)=>Promise<void>){dialog.value={title,fields,initial:{...initial},save};}
function editProject(p?:Row){edit(p?'编辑项目':'新建项目',[textField('name','项目名称'),{key:'description',label:'项目目标与交付要求',type:'textarea',required:true},dateField('startDate','开始日期'),dateField('endDate','结束日期'),{key:'priority',label:'优先级（1 最高）',type:'number',min:1,max:5},textField('location','工作地点',false)],p||{priority:3,startDate:new Date().toISOString().slice(0,10)},async v=>{const id=await api(p?`/projects/${p.id}`:'/projects',p?'PUT':'POST',v);await refresh();await openProject(projects.value.find(r=>r.id===(p?.id||id))!);});}
function editEmployee(e?:Row){edit(e?'编辑员工':'新增员工',[textField('name','姓名'),textField('employeeNo','工号'),selectField('departmentId','部门',departments.value),textField('position','岗位',false),textField('location','地点',false),{key:'weeklyHours',label:'每周工时',type:'number',min:1,max:168,required:true},{key:'defaultCapacity',label:'可用容量 %',type:'number',min:0,max:100,required:true}],e||{weeklyHours:40,defaultCapacity:100,departmentId:departments.value[0]?.id},async v=>{const id=await api(e?`/employees/${e.id}`:'/employees',e?'PUT':'POST',v);await refresh();await openEmployee(employees.value.find(r=>r.id===(e?.id||id))!);});}
function editSkill(s?:Row){edit(s?'编辑技能':'新增技能',[textField('name','技能名称'),selectField('categoryId','分类',categories.value),selectField('parentId','上级技能',skills.value.filter(r=>r.id!==s?.id),false),{key:'description',label:'技能说明',type:'textarea'}],s||{categoryId:categories.value[0]?.id},async v=>{await api(s?`/skills/${s.id}`:'/skills',s?'PUT':'POST',v);await refresh();});}
function editTask(t?:Row){edit(t?'编辑任务':'新增任务',[textField('name','任务名称'),{key:'description',label:'任务说明',type:'textarea'},dateField('startDate','开始日期'),dateField('endDate','结束日期'),{key:'estimatedHours',label:'预计工时',type:'number',min:1,required:true},{key:'priority',label:'优先级（1 最高）',type:'number',min:1,max:5},selectField('parentId','父任务',tasks.value.filter(r=>r.id!==t?.id),false),selectField('milestoneId','里程碑',milestones.value,false)],t||{startDate:selected.value!.startDate,endDate:selected.value!.endDate,priority:3,estimatedHours:8},async v=>{const id=await api(t?`/tasks/${t.id}`:`/projects/${selected.value!.id}/tasks`,t?'PUT':'POST',v);await reloadProject();await openTask(tasks.value.find(r=>r.id===(t?.id||id))!);});}
function addNeed(){edit('添加任务技能',[selectField('skillId','技能',skills.value),{key:'minLevel',label:'最低等级',type:'number',min:1,max:5,required:true},{key:'weight',label:'权重',type:'number',min:0,max:1,step:0.05,required:true},{key:'requirementType',label:'要求',type:'select',options:[{value:'REQUIRED',label:'必须具备'},{value:'PREFERRED',label:'优先考虑'}]}],{minLevel:3,weight:1,requirementType:'REQUIRED'},async v=>{await api(`/tasks/${task.value!.id}/skill-requirements`,'POST',v);await openTask(task.value!);});}
function addDependency(){edit('添加前置任务',[selectField('predecessorTaskId','前置任务',tasks.value.filter(t=>t.id!==task.value!.id)),{key:'dependencyType',label:'依赖类型',type:'select',options:['FS','SS','FF','SF'].map(v=>({value:v,label:{FS:'完成后开始',SS:'同时开始',FF:'同时完成',SF:'开始后完成'}[v]!}))}],{dependencyType:'FS'},async v=>{await api(`/tasks/${task.value!.id}/dependencies`,'POST',v);await openTask(task.value!);});}
function addEmployeeSkill(){edit('添加员工技能',[selectField('skillId','技能',skills.value.filter(s=>!employeeSkills.value.some(e=>e.skillId===s.id))),{key:'level',label:'熟练度 L1–L5',type:'number',min:1,max:5,required:true}],{level:3},async v=>{await api(`/employees/${employee.value!.id}/skills`,'PUT',[...employeeSkills.value,v]);await openEmployee(employee.value!);});}
function addAvailability(){edit('新增可用时间',[dateField('startDate','开始日期'),dateField('endDate','结束日期'),{key:'type',label:'类型',type:'select',options:[{value:'LEAVE',label:'休假'},{value:'TRAINING',label:'培训'},{value:'BUSINESS_TRIP',label:'出差'},{value:'BLOCKED',label:'不可安排'},{value:'AVAILABLE',label:'可用容量上限'}]},{key:'capacity',label:'容量 %（非可用类型按 0 处理）',type:'number',min:0,max:100,required:true},textField('remark','备注',false)],{type:'LEAVE',capacity:0},async v=>{await api(`/employees/${employee.value!.id}/availability`,'POST',v);alerts.value=await api('/replan/alerts');await openEmployee(employee.value!);});}
async function extractSkills(){await run(async()=>{const result=await api(`/employees/${employee.value!.id}/skills/ai-extract`,'POST',{text:skillText.value,source:'RESUME'});result.skills.forEach((s:Row)=>s.checked=Boolean(s.skillId));skillDraft.value=result;},'技能草稿已生成，确认后才会写入画像');}
async function acceptSkills(){const source=skillDraft.value!.source;const chosen=skillDraft.value!.skills.filter((s:Row)=>s.checked&&s.skillId);await run(async()=>{await api(`/employees/${employee.value!.id}/skills/ai-accept`,'POST',chosen.map((s:Row)=>({skillId:s.skillId,level:s.level,source,confidence:s.confidence})));skillDraft.value=null;await openEmployee(employee.value!);},'画像已更新');}
const draftCount=computed(()=>skillDraft.value?.skills.filter((s:Row)=>s.checked&&s.skillId).length||0);
function editMilestone(m?:Row){edit(m?'编辑里程碑':'新增里程碑',[textField('name','里程碑名称'),dateField('dueDate','目标日期'),{key:'sortOrder',label:'排序',type:'number',min:0,max:9999,required:true}],m||{sortOrder:0},async v=>{await api(m?`/milestones/${m.id}`:`/projects/${selected.value!.id}/milestones`,m?'PUT':'POST',v);await reloadProject();});}
function editDepartment(d?:Row){edit(d?'编辑部门':'新增部门',[textField('name','部门名称'),textField('code','编码',false),selectField('parentId','上级部门',departments.value.filter(x=>x.id!==d?.id),false)],d||{},async v=>{await api(d?`/departments/${d.id}`:'/departments',d?'PUT':'POST',v);await refresh();});}
function editCategory(c?:Row){edit(c?'编辑分类':'新增分类',[textField('name','分类名称'),textField('code','编码',false),{key:'sortOrder',label:'排序',type:'number',min:0,max:9999,required:true}],c||{sortOrder:0},async v=>{await api(c?`/skill-categories/${c.id}`:'/skill-categories',c?'PUT':'POST',v);await refresh();});}
function addAccount(){edit('创建账号',[textField('username','用户名（英文、数字）'),{key:'password',label:'初始密码（至少 12 字符）',type:'password',required:true},{key:'role',label:'角色',type:'select',options:['ADMIN','PROJECT_MANAGER','DEPARTMENT_MANAGER','EMPLOYEE'].map(value=>({value,label:value}))}],{role:'EMPLOYEE'},async v=>{await api('/auth/users','POST',v);accounts.value=await api('/auth/users');});}
async function remove(path:string,reload:()=>Promise<void>){if(!window.confirm('确定删除这条记录？此操作无法撤销。'))return;await run(async()=>{await api(path,'DELETE');await reload();},'已删除');}
async function generate(){await run(async()=>{progress.value='正在准备规划…';draft.value=await streamPlan(selected.value!.id,t=>progress.value=t);progress.value='';},'草稿已生成，修改并确认后才会保存为任务');}
function editDraftTask(t:Row,index:number){edit('修改规划任务',[textField('name','任务名称'),{key:'description',label:'说明',type:'textarea'},dateField('startDate','开始日期'),dateField('endDate','结束日期'),{key:'estimatedHours',label:'预计工时',type:'number',min:1,required:true}],t,async v=>{draft.value!.tasks[index]=v;});}
function addDraftNeed(t:Row){edit('添加规划技能',[selectField('skillId','技能',skills.value),{key:'minLevel',label:'最低等级',type:'number',min:1,max:5,required:true}],{minLevel:3},async v=>{t.skills.push({...v,weight:1,requirementType:'REQUIRED'});});}
async function solve(){await run(async()=>{const id=await api(`/projects/${selected.value!.id}/solve`,'POST',{strategy:strategy.value});plan.value=await api(`/resource-plans/${id}`);compare.value=null;compareWith.value='';candidateRows.value=await api(`/projects/${selected.value!.id}/candidates`);await reloadProject();review.value='';},'资源方案已生成');}
function assigned(taskId:number){return plan.value?.items.find((i:Row)=>i.task_id===taskId)?.employee_id||null;}
async function reassign(taskId:number,event:Event){const value=(event.target as HTMLSelectElement).value;await run(async()=>{plan.value=await api(`/resource-plans/${plan.value!.id}/items`,'PUT',candidateRows.value.map(c=>({taskId:c.taskId,employeeId:c.taskId===taskId?(value?Number(value):null):assigned(c.taskId)})));review.value='';},'人员安排已更新');}
async function loadPlan(id:number){plan.value=await api(`/resource-plans/${id}`);review.value='';compare.value=null;compareWith.value='';if(plan.value!.status==='DRAFT')candidateRows.value=await api(`/projects/${selected.value!.id}/candidates`);}
async function loadCompare(){if(!compareWith.value||!plan.value)return;compare.value=await api(`/resource-plans/compare?left=${plan.value.id}&right=${compareWith.value}`);}
const strategyLabel=(s:string)=>({BALANCED:'平衡',BEST_SKILL_MATCH:'技能优先',LOWEST_RISK:'负载均衡'} as Row)[s]||s;
const side=(s:Row|undefined)=>!s||s.gap?'未分配':`${s.employeeName} ${s.allocation}%`;
const differs=(r:Row)=>side(r.left)!==side(r.right);
async function runImpact(){await run(async()=>{impact.value=await api(`/projects/${selected.value!.id}/replan/impact`);});}
async function replanNow(){await run(async()=>{const id=await api(`/projects/${selected.value!.id}/replan`,'POST',{strategy:strategy.value});plan.value=await api(`/resource-plans/${id}`);candidateRows.value=await api(`/projects/${selected.value!.id}/candidates`);review.value='';impact.value=null;await reloadProject();},'重规划方案已生成，确认生效时将与旧方案原子换班');}
const impactType=(t:string)=>({UNAVAILABLE:'休假/不可用',EMPLOYEE_INACTIVE:'成员停用',TASK_DRIFT:'任务变更',SKILL_DRIFT:'技能要求变化',PROJECT_WINDOW:'项目周期变化'} as Row)[t]||t;
async function uploadResume(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);form.append('source','RESUME');const result=await apiForm(`/employees/${employee.value!.id}/skills/ai-extract-file`,form);result.skills.forEach((s:Row)=>s.checked=Boolean(s.skillId));skillDraft.value=result;},`已解析 ${file.name}`);}
async function runAdvise(){adviseText.value=(await api(`/capability/advise?weeks=${sdWeeks.value}`,'POST')).text;}
async function runScenario(){scenario.value=await api(`/capability/scenario?weeks=${sdWeeks.value}`);trends.value=null;}
async function runTrends(){trends.value=await api('/capability/trends');scenario.value=null;}
async function loadCapability(){[supplyDemand.value,keyPeople.value]=await Promise.all([api(`/capability/supply-demand?weeks=${sdWeeks.value}`),api('/capability/key-people')]);}
async function loadLeaveImpact(){leaveImpact.value=await api(`/capability/leave-impact?employeeId=${leavePick.value}`);}
async function loadNotify(){notify.value=await api('/system/notify/status');notifyLog.value=await api('/system/notify/log?limit=10');}
async function loadTimeline(){timeline.value=await api('/allocations/timeline');}
const heat=(v:number|undefined)=>!v?'':(v>=100?'l-high':v>=60?'l-mid':'l-low');
const tip=(r:Row,w:string)=>{const end=new Date(w);end.setDate(end.getDate()+6);const weekEnd=end.toISOString().slice(0,10);return r.bookings.filter((b:Row)=>b.start<=weekEnd&&b.end>=w).map((b:Row)=>`${b.projectName} · ${b.taskName} · ${b.allocation}% · ${b.start}→${b.end}`).join('\n')||'本周无占用';};
async function searchSemantic(){semantic.value=await api(`/skills/semantic?q=${encodeURIComponent(semanticQuery.value)}`);}
const GANTT_CELL=22,GANTT_NAME=190;
const gantt=computed(()=>{
  const ts=tasks.value.filter(t=>t.startDate&&t.endDate);
  if(!ts.length) return null;
  const start=ts.reduce((m,t)=>t.startDate<m?t.startDate:m,ts[0].startDate);
  const end=ts.reduce((m,t)=>t.endDate>m?t.endDate:m,ts[0].endDate);
  const days:string[]=[]; const cursor=new Date(start+'T00:00:00Z'); const last=new Date(end+'T00:00:00Z');
  while(cursor<=last&&days.length<366){days.push(cursor.toISOString().slice(0,10));cursor.setUTCDate(cursor.getUTCDate()+1);}
  return {ts,days,start,truncated:days.length>=366&&cursor<=last};
});
const isWeekend=(d:string)=>{const w=new Date(d+'T00:00:00Z').getUTCDay();return w===0||w===6;};
const ganttLeft=(date:string|null)=>{if(!date) return null;const i=gantt.value?.days.indexOf(date);return i===undefined||i<0?null:GANTT_NAME+i*GANTT_CELL;};
const ganttBar=(t:Row)=>{const l=ganttLeft(t.startDate),r=ganttLeft(t.endDate);return l===null||r===null?null:{left:l+'px',width:(r-l+GANTT_CELL)+'px'};};
</script>

<template>
<div v-if="loading" class="boot">正在连接工作台…</div>
<div v-else-if="!user" class="login-shell"><div class="login-art"><div class="brand"><Layers3 :size="30"/> 序 <small>ORCHESTRATOR</small></div><div><span class="eyebrow">FROM INTENT TO IMPACT</span><h1>让合适的人，<br>成就下一个项目。</h1><p>连接项目目标、团队能力与可用时间。<br>从一个想法，走向一份可执行的人员安排。</p></div><div class="art-lines"><span>01 / 理解目标</span><span>02 / 匹配能力</span><span>03 / 协同交付</span></div></div><form class="login-form" @submit.prevent="signIn"><span class="eyebrow">YOUR TEAM. IN SYNC.</span><h2>欢迎回到工作台</h2><p class="muted">使用团队账号登录，开始规划。</p><label>用户名<input v-model="username" required autocomplete="username"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"></label><p v-if="loginError" class="error" role="alert">{{loginError}}</p><button :disabled="busy">{{busy?'登录中…':'进入工作台'}} <ArrowUpRight :size="18"/></button><p class="login-note">首次启动由 ADMIN_PASSWORD 创建管理员账号。</p></form></div>
<div v-else class="app-shell">
<aside class="sidebar"><a class="brand" href="#" @click.prevent="tab='projects';selected=null"><Layers3 :size="28"/><b>序</b><small>ORCHESTRATOR</small></a><span class="nav-label">工作空间</span><nav><button :class="{active:tab==='projects'}" @click="tab='projects'"><Layers3 :size="18"/>项目与编排<span>{{projects.length}}</span><i v-if="alerts.length" class="alert-dot" :title="alerts.length+' 个项目的方案存在冲突'"></i></button><button :class="{active:tab==='employees'}" @click="tab='employees'"><Users :size="18"/>团队成员<span>{{employees.length}}</span></button><button :class="{active:tab==='skills'}" @click="tab='skills'"><BookOpen :size="18"/>能力图谱</button><button :class="{active:tab==='timeline'}" @click="tab='timeline';run(loadTimeline)"><CalendarRange :size="18"/>资源排期</button><button :class="{active:tab==='capability'}" @click="tab='capability';run(loadCapability)"><Compass :size="18"/>能力决策</button><button :class="{active:tab==='settings'}" @click="tab='settings';admin&&run(loadNotify)"><Settings2 :size="18"/>组织与设置</button></nav><div class="sidebar-bottom"><div class="mode"><i :class="{live:mode==='live'}"></i>{{mode==='demo'?'演示模式 · 模板规划':mode==='live'?'AI 模型已启用':'AI 未配置'}}</div><p>规划由 AI 辅助<br>分配由规则约束，确认由你决定。</p><div class="profile"><div class="avatar">{{user.username.slice(0,1).toUpperCase()}}</div><div><b>{{user.username}}</b><small>{{user.roles[0]}}</small></div><button class="icon-button" aria-label="退出登录" @click="run(signOut)"><LogOut :size="16"/></button></div></div></aside>
<main><header class="topbar"><span>工作空间 <ChevronRight :size="14"/> {{({projects:'项目与编排',employees:'团队成员',skills:'能力图谱',timeline:'资源排期',capability:'能力决策',settings:'组织与设置'} as Row)[tab]}}</span><button class="text-button" :disabled="busy" @click="run(refresh,'数据已刷新')"><RefreshCw :size="14"/>刷新数据</button></header>
<div class="content"><div v-if="error" class="alert error" role="alert">{{error}}<button aria-label="关闭提示" @click="error=''">×</button></div><div v-if="notice" class="alert success" role="status">{{notice}}<button aria-label="关闭提示" @click="notice=''">×</button></div><div v-if="busy" class="working" role="status">{{progress||'正在处理，请稍候…'}}</div>

<template v-if="tab==='projects' && !selected"><section class="page-title"><div><span class="eyebrow">PROJECT STUDIO</span><h1>把目标，变成团队的下一步。</h1><p>从项目规划到人员安排，在一个工作台中完成。</p></div><button v-if="canPlan" @click="editProject()"><Plus :size="17"/>新建项目</button></section><div v-if="alerts.length" class="gap replan-alerts"><b>重规划提醒：{{alerts.length}} 个项目的生效方案与最新基础数据存在冲突</b><div v-for="al in alerts" :key="al.projectId" class="list-row"><span>{{al.projectName}}</span><small>{{al.conflictCount}} 项冲突 · {{al.conflicts[0]?.detail||''}}</small><button class="text-button" @click="run(()=>openProject(projects.find(p=>p.id===al.projectId)!))">查看项目</button></div></div>
<section class="hero"><div><span class="badge light"><Sparkles :size="13"/>项目规划助手</span><h2>下一个项目，<br>需要怎样的团队？</h2><p>描述目标与交付时间，让规划从这里开始。</p><button v-if="canPlan" class="cream" @click="editProject()">开始规划 <ArrowUpRight :size="16"/></button></div><div class="orbit"><div class="orbit-core"><Layers3 :size="35"/><span>项目目标</span></div><span class="orbit-tag tag-one">能力匹配</span><span class="orbit-tag tag-two">可用时间</span><span class="orbit-tag tag-three">团队协作</span></div></section><div class="section-heading"><h2>进行中的规划 <small>{{projects.length}}</small></h2><span class="muted">每个项目，都有合适的安排</span></div><div v-if="!projects.length" class="empty"><Layers3 :size="32"/><h3>从第一个项目开始</h3><p>新建项目，添加任务或使用 AI 生成可编辑的规划。</p></div><div class="project-grid"><button v-for="p in projects" :key="p.id" class="project-card" @click="run(()=>openProject(p))"><div class="card-top"><span class="project-symbol"><Layers3 :size="19"/></span><span class="badge">{{p.status==='PLANNING'?'规划中':p.status}}</span></div><h3>{{p.name}}</h3><p>{{p.description||'尚未填写项目目标'}}</p><footer><span><CalendarDays :size="13"/>{{p.endDate||'待定'}} 交付</span><ArrowUpRight :size="18"/></footer></button></div></template>

<template v-if="tab==='projects' && selected"><button class="back text-button" @click="selected=null"><ArrowLeft :size="15"/>全部项目</button><section class="page-title"><div><span class="eyebrow">PROJECT / {{String(selected.id).padStart(3,'0')}}</span><h1>{{selected.name}}</h1><p>{{selected.startDate}} — {{selected.endDate}} · {{selected.description}}</p></div><div class="actions" v-if="canPlan"><button class="secondary" @click="editProject(selected)"><Pencil :size="14"/>编辑项目</button><button class="icon-button danger" aria-label="删除项目" @click="remove(`/projects/${selected.id}`,async()=>{selected=null;await refresh()})"><Trash2 :size="17"/></button></div></section><div class="workflow"><span :class="{done:tasks.length}"><b>01</b>需求与任务</span><ChevronRight :size="16"/><span :class="{done:plan}"><b>02</b>能力匹配与求解</span><ChevronRight :size="16"/><span :class="{done:plan?.status==='CONFIRMED'}"><b>03</b>确认人员方案</span></div>
<section v-if="!tasks.length && !draft" class="planning-empty"><Sparkles :size="28"/><h2>先把项目拆解成可执行的任务</h2><p>生成规划后，可以逐项修改名称、日期、工时和能力需求。</p><div class="actions" v-if="canPlan"><button :disabled="busy||mode==='off'" @click="generate"><Sparkles :size="16"/>{{mode==='demo'?'生成演示规划':'AI 生成规划'}}</button><button class="secondary" @click="editTask()">手动添加任务</button></div><small v-if="mode==='demo'">当前使用固定演示模板，不会调用大模型。</small><small v-if="mode==='off'">AI 尚未启用，仍可手动创建任务并求解。</small></section>
<section v-if="draft" class="panel draft"><div class="section-heading"><div><span class="eyebrow">PLAN PREVIEW</span><h2>检查并完善规划</h2></div><div class="actions"><button class="secondary" :disabled="busy" @click="generate">重新生成</button><button :disabled="busy" @click="run(async()=>{await api(`/projects/${selected!.id}/ai-plan/accept`,'POST',draft);draft=null;await reloadProject()},'规划已保存为项目任务')"><Check :size="16"/>确认导入任务</button></div></div><p>{{draft.summary}}</p><article v-for="(t,i) in draft.tasks" :key="i" class="draft-task"><div class="section-heading"><h3>{{Number(i)+1}}. {{t.name}}</h3><button class="text-button" @click="editDraftTask(t,Number(i))"><Pencil :size="14"/>编辑</button></div><p>{{t.startDate}} → {{t.endDate}} · {{t.estimatedHours}} 工时</p><div class="tags"><span v-for="(n,j) in t.skills" :key="j" class="badge">{{nameOf(skills,n.skillId)}} L{{n.minLevel}} <button aria-label="移除技能" @click="t.skills.splice(j,1)">×</button></span><button class="text-button" @click="addDraftNeed(t)">+ 技能需求</button></div><label class="inline-label">前置任务<select multiple v-model="t.predecessorIndexes"><option v-for="(prev,j) in draft.tasks.slice(0,i)" :key="j" :value="j">{{prev.name}}</option></select></label><button class="text-button danger" @click="draft.tasks.splice(i,1);draft.tasks.forEach((r:Row)=>r.predecessorIndexes=[])">移除此任务（清空依赖后请重新选择）</button></article></section>
<section v-if="tasks.length" class="panel"><div class="section-heading"><h2>任务清单 <small>{{tasks.length}}</small></h2><div class="actions" v-if="canPlan"><button class="secondary" @click="editTask()"><Plus :size="15"/>添加任务</button><select v-model="strategy" aria-label="求解策略" title="求解策略"><option value="BALANCED">平衡</option><option value="BEST_SKILL_MATCH">技能优先</option><option value="LOWEST_RISK">负载均衡</option></select><button :disabled="busy" @click="solve"><Sparkles :size="15"/>生成资源方案</button></div></div><div class="table-scroll"><table><thead><tr><th>任务 / WBS</th><th>计划时间</th><th>工时</th><th>优先级</th><th></th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id" :class="{selected:task?.id===t.id}"><td><button class="link" @click="run(()=>openTask(t))">{{t.parentId?'↳ ':''}}{{t.name}}</button></td><td>{{t.startDate||'待定'}} → {{t.endDate||'待定'}}</td><td>{{t.estimatedHours}} h</td><td>P{{t.priority}}</td><td><div class="actions" v-if="canPlan"><button class="icon-button" aria-label="编辑任务" @click="editTask(t)"><Pencil :size="14"/></button><button class="icon-button danger" aria-label="删除任务" @click="remove(`/tasks/${t.id}`,async()=>{task=null;await reloadProject()})"><Trash2 :size="14"/></button></div></td></tr></tbody></table></div><p class="hint">点击任务名称维护技能与依赖。按周一至周五、每天均匀投入计算；当前求解固定日期内的人员安排。</p></section>
<section v-if="gantt" class="panel"><div class="section-heading"><h2>项目甘特图</h2><span class="muted">{{gantt.days.length}} 天 · {{gantt.start}} 起</span></div>
<div class="gantt-scroll"><div class="gantt" :style="{width:GANTT_NAME+gantt.days.length*GANTT_CELL+'px'}">
<div class="gantt-row gantt-head"><div class="gantt-name">任务</div><div v-for="day in gantt.days" :key="day" class="gantt-cell head" :class="{weekend:isWeekend(day)}">{{day.slice(8)}}</div><span v-for="m in milestones.filter(m=>ganttLeft(m.dueDate)!==null)" :key="m.id" class="gantt-mark" :style="{left:ganttLeft(m.dueDate)+'px'}" :title="m.name+' · '+m.dueDate"></span></div>
<div v-for="t in gantt.ts" :key="t.id" class="gantt-row"><div class="gantt-name" :title="t.name">{{t.parentId?'↳ ':''}}{{t.name}}</div><div v-for="day in gantt.days" :key="day" class="gantt-cell" :class="{weekend:isWeekend(day)}"></div><div v-if="ganttBar(t)" class="gantt-bar" :class="'p'+(t.priority||3)" :style="ganttBar(t)!" :title="t.name+' · '+t.startDate+' → '+t.endDate+' · P'+(t.priority||3)"></div></div>
</div></div>
<p class="hint">按日展示任务区间，底色为周末；菱形为里程碑；条形颜色对应优先级（P1 最暖）。依赖关系暂未画箭头，可在任务详情查看。</p><p v-if="gantt.truncated" class="hint">时间窗过长，仅显示前 366 天。</p></section>
<section v-if="task" class="panel"><div class="section-heading"><h2>{{task.name}} · 能力与依赖</h2><button class="icon-button" @click="task=null" aria-label="关闭任务详情">×</button></div><div class="two-columns"><div><div class="section-heading"><h3>技能需求</h3><button v-if="canPlan" class="text-button" @click="addNeed">+ 添加技能</button></div><div v-for="n in needs" :key="n.id" class="list-row"><span>{{nameOf(skills,n.skillId)}} <b>L{{n.minLevel}}</b> · {{n.requirementType==='REQUIRED'?'必须':'优先'}}</span><button v-if="canPlan" class="icon-button" aria-label="删除技能需求" @click="remove(`/tasks/${task.id}/skill-requirements/${n.id}`,()=>openTask(task!))">×</button></div><p v-if="!needs.length" class="muted">暂无技能限制，所有可用员工均可参与匹配。</p></div><div><div class="section-heading"><h3>前置依赖</h3><button v-if="canPlan" class="text-button" @click="addDependency">+ 添加依赖</button></div><div v-for="d in dependencies" :key="d.id" class="list-row"><span>{{nameOf(tasks,d.predecessorTaskId)}} · {{d.dependencyType}}</span><button v-if="canPlan" class="icon-button" aria-label="删除依赖" @click="remove(`/tasks/${task.id}/dependencies/${d.id}`,()=>openTask(task!))">×</button></div><p v-if="!dependencies.length" class="muted">暂无前置任务。</p></div></div></section>
<section class="panel"><div class="section-heading"><h2>里程碑</h2><button class="text-button" v-if="canPlan" @click="editMilestone()">+ 添加里程碑</button></div><div class="tags"><div v-for="m in milestones" :key="m.id" class="milestone"><CalendarDays :size="16"/><b>{{m.name}}</b><span>{{m.dueDate}}</span><button v-if="canPlan" class="icon-button" aria-label="编辑里程碑" @click="editMilestone(m)"><Pencil :size="13"/></button><button v-if="canPlan" class="icon-button" aria-label="删除里程碑" @click="remove(`/milestones/${m.id}`,reloadProject)">×</button></div><p v-if="!milestones.length" class="muted">暂无里程碑。</p></div></section>
<section v-if="plans.length" class="panel"><div class="section-heading"><h2>资源方案</h2><select aria-label="选择资源方案" :value="plan?.id||''" @change="run(()=>loadPlan(Number(($event.target as HTMLSelectElement).value)))"><option value="" disabled>选择历史版本</option><option v-for="p in plans" :key="p.id" :value="p.id">方案 v{{p.version}} · {{p.status}}</option></select><select v-model="compareWith" aria-label="对比方案" @change="run(loadCompare)"><option value="" disabled>对比其他版本</option><option v-for="p in plans.filter(p=>p.id!==plan?.id)" :key="p.id" :value="p.id">对比 v{{p.version}}</option></select></div><template v-if="plan"><div class="plan-banner"><ShieldCheck :size="22"/><div><b>方案 v{{plan.version}} · {{plan.status==='CONFIRMED'?'已确认生效':plan.status==='DRAFT'?'待人工确认':'已撤销'}}</b><p>约束评分 {{plan.score_text}} · {{plan.items.length}} 个任务已分配</p></div><span class="badge" :class="{'warning':plan.gaps.length}">{{plan.gaps.length?'存在 '+plan.gaps.length+' 项缺口':'无未分配任务'}}</span></div><div class="table-scroll"><table class="plan-items"><thead><tr><th>任务</th><th>推荐成员</th><th>投入比例</th><th>时间</th></tr></thead><tbody><tr v-for="item in plan.items" :key="item.id"><td>{{item.task_name}}</td><td>{{item.employee_name}}</td><td><span class="capacity"><i :style="{width:item.allocation+'%'}"></i></span>{{item.allocation}}%</td><td>{{item.start_date}} → {{item.end_date}}</td></tr></tbody></table></div><div v-for="g in plan.gaps" :key="g.taskId" class="gap"><b>{{g.taskName}}</b> · {{g.reason}}<div v-if="g.missingSkills?.length" class="tags"><span v-for="s in g.missingSkills" :key="s.skillId" class="badge warning">{{s.skillName}} 需 L{{s.requiredLevel}}，全公司无人达标</span></div></div>
<div v-if="plan.gapSummary?.length" class="gap"><b>能力缺口汇总</b><div v-for="s in plan.gapSummary" :key="s.skillId" class="list-row"><span>{{s.skillName}} 需 L{{s.requiredLevel}}</span><small>{{s.taskCount}} 个任务 · {{s.totalHours}} 工时 · {{s.start}} → {{s.end}} · {{s.workdays}} 个工作日</small></div></div>
<div v-if="plan.warnings?.length" class="gap load-warn"><b>跨项目负载预警（周占用 ≥80%）</b><div v-for="(w,i) in plan.warnings.slice(0,12)" :key="i" class="list-row"><span>{{w.employeeName}} · {{w.week}} 周</span><small>跨项目合计占用 {{w.load}}%</small></div><small v-if="plan.warnings.length>12">仅显示前 12 条，共 {{plan.warnings.length}} 条。</small></div>
<div v-if="impact" class="gap impact-list"><b>变更影响分析（{{impact.conflictCount}} 项冲突）</b><div v-for="(c,i) in impact.conflicts" :key="i" class="list-row"><span>{{impactType(c.type)}}：{{c.employeeName}}{{c.taskId?' · '+c.taskName:''}}</span><small>{{c.detail}}</small></div><p v-if="!impact.conflictCount" class="muted">当前生效方案与最新基础数据无冲突。</p></div>
<div v-if="compare" class="compare"><div class="section-heading"><h3>方案对比 <small>v{{compare.left.version}}（{{strategyLabel(compare.left.strategy)}}）↔ v{{compare.right.version}}（{{strategyLabel(compare.right.strategy)}}）</small></h3><button class="icon-button" aria-label="关闭对比" @click="compare=null;compareWith=''">×</button></div><div class="table-scroll"><table><thead><tr><th>任务</th><th>方案 v{{compare.left.version}}</th><th>方案 v{{compare.right.version}}</th></tr></thead><tbody><tr v-for="r in compare.rows" :key="r.taskId"><td>{{r.taskName}}</td><td>{{side(r.left)}}</td><td :class="{changed:differs(r)}">{{side(r.right)}}</td></tr></tbody></table></div><p class="hint">评分 {{compare.left.score}} ↔ {{compare.right.score}} · 缺口 {{compare.left.gaps}} ↔ {{compare.right.gaps}}</p></div><details v-if="plan.status==='DRAFT' && canPlan"><summary>查看候选人员 / 人工调整</summary><div v-for="c in candidateRows" :key="c.taskId" class="list-row"><span>{{c.taskName}}</span><select :aria-label="'分配 '+c.taskName" :value="assigned(c.taskId)||''" :disabled="busy" @change="reassign(c.taskId,$event)"><option value="">暂不分配</option><option v-for="person in c.candidates" :key="person.employeeId" :value="person.employeeId">{{person.name}} · 匹配 {{person.score}}% · 投入 {{person.allocation/100}}%</option></select></div></details><div class="plan-actions" v-if="canPlan"><button :disabled="busy||plan.status!=='DRAFT'||plan.gaps.length>0" @click="run(async()=>{plan=await api(`/resource-plans/${plan!.id}/confirm`,'POST');await reloadProject()},'方案已确认，正式资源分配已生效')"><Check :size="16"/>确认并生效</button><button class="secondary" :disabled="busy||mode==='off'" @click="run(async()=>{review=(await api(`/resource-plans/${plan!.id}/review`,'POST')).text})"><Sparkles :size="15"/>{{mode==='demo'?'查看演示解释':'AI 解释方案'}}</button><button v-if="plan.status==='DRAFT'&&plans.some(p=>p.status==='CONFIRMED')" class="secondary" :disabled="busy||mode==='off'" @click="run(async()=>{review=(await api(`/resource-plans/${plan!.id}/explain-diff`,'POST')).text})"><Sparkles :size="15"/>{{mode==='demo'?'重规划差异说明':'AI 解释重规划差异'}}</button><button v-if="plan.status==='CONFIRMED'" class="secondary" :disabled="busy" @click="runImpact"><AlertTriangle :size="15"/>变更影响分析</button><button v-if="plan.status==='CONFIRMED'" :disabled="busy" @click="replanNow"><RefreshCw :size="15"/>重新求解（重规划）</button><button v-if="plan.status!=='ARCHIVED'" class="text-button danger" :disabled="busy" @click="run(async()=>{if(window.confirm('撤销后将释放该方案的资源占用，是否继续？')){plan=await api(`/resource-plans/${plan!.id}/cancel`,'POST');await reloadProject()}})">撤销方案</button></div><div v-if="review" class="review"><span class="eyebrow">{{mode==='demo'?'演示规则说明':'AI 方案解释'}}</span><p>{{review}}</p></div></template><p v-else class="muted">选择方案查看分配与风险。</p></section></template>

<template v-if="tab==='employees'"><section class="page-title"><div><span class="eyebrow">PEOPLE & POTENTIAL</span><h1>每一种能力，都被看见。</h1><p>维护团队画像，让人员匹配有据可依。</p></div><button v-if="canPeople" @click="editEmployee()"><Plus :size="16"/>新增员工</button></section><div class="stats"><div><span>团队成员</span><b>{{employees.length}} <small>人</small></b></div><div><span>组织部门</span><b>{{departments.length}} <small>个</small></b></div><div><span>技能库</span><b>{{skills.length}} <small>项</small></b></div></div><section class="panel"><div class="section-heading"><h2>成员列表</h2><input class="search" v-model="search" placeholder="搜索姓名 / 工号" aria-label="搜索成员"></div><div class="table-scroll"><table><thead><tr><th>成员</th><th>部门 / 岗位</th><th>每周工时</th><th>默认容量</th><th></th></tr></thead><tbody><tr v-for="e in filteredEmployees" :key="e.id" :class="{selected:employee?.id===e.id}"><td><button class="person-link" @click="run(()=>openEmployee(e))"><span class="avatar">{{e.name.slice(0,1)}}</span><span><b>{{e.name}}</b><small>{{e.employeeNo}}</small></span></button></td><td>{{nameOf(departments,e.departmentId)}}<small class="cell-small">{{e.position}}</small></td><td>{{e.weeklyHours}} h</td><td>{{e.defaultCapacity}}%</td><td><div class="actions" v-if="canPeople"><button class="icon-button" aria-label="编辑员工" @click="editEmployee(e)"><Pencil :size="14"/></button><button class="icon-button danger" aria-label="删除员工" @click="remove(`/employees/${e.id}`,async()=>{employee=null;await refresh()})"><Trash2 :size="14"/></button></div></td></tr></tbody></table></div><div v-if="!employees.length" class="empty"><Users :size="28"/><h3>团队尚未加入</h3><p>先在组织设置中创建部门，再添加成员。</p><button v-if="admin&&mode==='demo'" class="secondary" @click="run(async()=>{await api('/system/demo-data','POST');await refresh()},'已载入 10 位演示员工及技能')">载入 10 位演示员工</button></div></section><section v-if="employee" class="panel"><div class="section-heading"><h2>{{employee.name}} · 能力画像</h2><button class="text-button" v-if="canPeople" @click="addEmployeeSkill">+ 添加技能</button></div><div class="skill-grid"><div v-for="s in employeeSkills" :key="s.skillId" class="skill-profile"><div><b>{{s.skillName}}</b><span>L{{s.level}}</span></div><div class="level-dots"><i v-for="n in 5" :key="n" :class="{filled:n<=s.level}"></i></div><div v-if="canPeople" class="actions"><select v-model.number="s.level" :aria-label="'技能等级 '+s.skillName"><option v-for="n in 5" :key="n" :value="n">L{{n}}</option></select><button class="text-button" :disabled="busy" @click="run(async()=>{await api(`/employees/${employee!.id}/skills`,'PUT',employeeSkills);await openEmployee(employee!)},'技能已保存')">保存</button><button class="icon-button" aria-label="移除员工技能" @click="run(async()=>{await api(`/employees/${employee!.id}/skills`,'PUT',employeeSkills.filter(r=>r.skillId!==s.skillId));await openEmployee(employee!)})">×</button></div></div></div><p v-if="!employeeSkills.length" class="muted">暂无技能画像。</p><template v-if="canPeople&&mode!=='off'"><div class="section-heading spaced"><h3>AI 能力识别</h3><span class="muted">{{mode==='demo'?'演示规则识别':'AI 模型识别'}} · 结果仅为草稿</span></div><p class="muted">粘贴简历或项目经历，识别技能并归一匹配技能库；勾选确认后才写入画像（来源标记为 RESUME / PROJECT / AI）。</p><div v-if="evidence.length" class="tags evidence"><span v-for="ev in evidence" :key="ev.skill_id" class="badge">历史：{{ev.skill_name}} · {{ev.project_count}} 项目 · {{ev.total_hours}} 工时<template v-if="(ev.suggested_level||0)>(ev.profile_level||0)"><small>画像 L{{ev.profile_level||'—'}} / 建议 L{{ev.suggested_level}}</small><button class="text-button" :disabled="busy" @click="run(async()=>{await api(`/employees/${employee!.id}/skills/ai-accept`,'POST',[{skillId:ev.skill_id,level:ev.suggested_level,source:'PROJECT',confidence:0.8}]);await openEmployee(employee!)},'已按历史任务补录技能')">采纳</button></template></span></div><textarea v-model="skillText" class="profile-text" aria-label="经历文本" placeholder="例如：负责工业视觉项目，精通 Java 与 Spring Boot，熟悉 MES 对接…"></textarea><div class="actions pad-top"><label class="file-button"><input type="file" accept=".txt,.md,.pdf,.docx" aria-label="选择简历文件" @change="uploadResume"><Paperclip :size="14"/>上传简历文件</label><button class="secondary" :disabled="busy||!skillText.trim()" @click="extractSkills"><Sparkles :size="14"/>识别技能</button></div><div v-if="skillDraft" class="draft-skills"><div class="section-heading"><h3>技能草稿（{{skillDraft.skills.length}} 项）</h3><div class="actions"><button :disabled="busy||!draftCount" @click="acceptSkills"><Check :size="14"/>确认写入 {{draftCount}} 项</button></div></div><table v-if="skillDraft.skills.length"><thead><tr><th></th><th>技能</th><th>等级</th><th>置信度</th><th>依据</th></tr></thead><tbody><tr v-for="s in skillDraft.skills" :key="s.name" :class="{off:!s.skillId}"><td><input type="checkbox" v-model="s.checked" :disabled="!s.skillId" :aria-label="'采纳 '+s.name"></td><td><b>{{s.skillName||s.name}}</b><small v-if="!s.skillId" class="cell-small"><template v-if="s.suggestedSkillId">相似技能：{{s.suggestedSkillName}}（{{Math.round((s.similarity||0)*100)}}%）<button class="text-button" @click="s.skillId=s.suggestedSkillId;s.skillName=s.suggestedSkillName;s.checked=true">采用</button></template><template v-else>未匹配技能库，请先创建</template></small><small v-else-if="s.matchedBy==='ALIAS'" class="cell-small">别名「{{s.name}}」命中</small></td><td><select v-model.number="s.level" :disabled="!s.skillId" :aria-label="'等级 '+s.name"><option v-for="n in 5" :key="n" :value="n">L{{n}}</option></select></td><td>{{Math.round(s.confidence*100)}}%</td><td>{{s.reason}}</td></tr></tbody></table><p v-else class="muted">未识别到技能库中的技能，请补充经历文本或先在能力图谱中创建技能。</p></div></template><div class="section-heading spaced"><h3>可用时间与休假</h3><button class="text-button" v-if="canPeople" @click="addAvailability">+ 新增记录</button></div><div v-for="a in availability" :key="a.id" class="list-row"><span>{{a.startDate}} → {{a.endDate}} · {{a.type}} · {{a.capacity}}% · {{a.remark}}</span><button v-if="canPeople" class="icon-button" aria-label="删除可用时间" @click="remove(`/employees/${employee.id}/availability/${a.id}`,()=>openEmployee(employee!))">×</button></div><p v-if="!availability.length" class="muted">暂无特殊安排，使用默认容量。</p></section></template>

<template v-if="tab==='skills'"><section class="page-title"><div><span class="eyebrow">CAPABILITY LIBRARY</span><h1>建立团队共同的能力语言。</h1><p>统一技能名称与等级，减少匹配中的信息偏差。</p></div><button v-if="canPeople" @click="editSkill()"><Plus :size="16"/>新增技能</button></section><section class="panel"><div class="section-heading"><h2>语义检索</h2><div class="actions"><input class="search" v-model="semanticQuery" placeholder="按含义查找技能，如：前端框架" aria-label="语义检索" @keyup.enter="run(searchSemantic)"><button class="secondary" :disabled="busy||!semanticQuery.trim()" @click="run(searchSemantic)">检索</button></div></div><template v-if="semantic"><p v-if="!semantic.status.enabled" class="muted">语义检索未启用：设置 SKILL_SEMANTIC_ENABLED=true 并使用支持 pgvector 的 PostgreSQL 后生效（默认关闭，不影响其它功能）。</p><template v-else><div class="tags"><span v-for="r in semantic.rows" :key="r.skillId" class="badge">{{r.skillName}} · {{Math.round(r.score*100)}}%</span></div><p v-if="!semantic.rows.length" class="muted">没有相似技能。</p></template></template><p v-else class="muted">可选能力：按语义相似度检索技能库（本地确定性向量，默认关闭；启用后 AI 技能识别的未匹配名也会获得向量建议）。</p></section><div class="skill-catalog"><article v-for="s in skills" :key="s.id" class="panel"><div class="section-heading"><span class="badge">{{nameOf(categories,s.categoryId)}}</span><div class="actions" v-if="canPeople"><button class="icon-button" aria-label="编辑技能" @click="editSkill(s)"><Pencil :size="14"/></button><button class="icon-button danger" aria-label="删除技能" @click="remove(`/skills/${s.id}`,refresh)"><Trash2 :size="14"/></button></div></div><h2>{{s.name}}</h2><p class="muted">{{s.description||'暂无技能说明'}}</p><button class="text-button" v-if="canPeople" @click="edit('添加技能别名',[textField('alias','别名')],{},async v=>{await api(`/skills/${s.id}/aliases`,'POST',v);notice='别名已保存'})">+ 添加别名</button><button class="text-button" @click="run(async()=>{s.aliases=await api(`/skills/${s.id}/aliases`)})">查看别名</button><div class="tags"><span class="badge" v-for="a in s.aliases" :key="a.id">{{a.alias}}<button v-if="canPeople" aria-label="删除别名" @click="remove(`/skills/${s.id}/aliases/${a.id}`,async()=>{s.aliases=await api(`/skills/${s.id}/aliases`)})">×</button></span></div></article></div><div v-if="!skills.length" class="empty"><BookOpen :size="30"/><h3>为团队建立第一项技能</h3><p>先在组织设置创建分类，再添加技能。</p></div></template>

<template v-if="tab==='timeline'"><section class="page-title"><div><span class="eyebrow">TEAM CAPACITY</span><h1>全员负荷，一览无余。</h1><p>按周聚合各项目的资源占用，识别过载与空闲，支撑跨项目调度。</p></div><button class="text-button" :disabled="busy" @click="run(loadTimeline,'排期已刷新')"><RefreshCw :size="14"/>刷新</button></section>
<section class="panel"><div class="section-heading"><h2>资源排期 <small>{{timeline?.rows?.length||0}} 位成员 · {{timeline?.weeks?.length||0}} 周</small></h2><div class="legend"><span class="heat l-low">较空 &lt;60%</span><span class="heat l-mid">较高 60–99%</span><span class="heat l-high">过载 ≥100%</span></div></div>
<div v-if="timeline?.rows?.length" class="table-scroll"><table class="timeline-table"><thead><tr><th>成员</th><th v-for="w in timeline.weeks" :key="w">{{w.slice(5)}}</th></tr></thead><tbody><tr v-for="r in timeline.rows" :key="r.employeeId"><td><b>{{r.name}}</b><small class="cell-small">{{r.bookings.length}} 项占用 · {{r.weeklyHours}} h/周</small></td><td v-for="w in timeline.weeks" :key="w" class="heat" :class="heat(r.load[w])" :title="tip(r,w)">{{r.load[w]?r.load[w]+'%':''}}</td></tr></tbody></table></div>
<div v-else class="empty"><Users :size="30"/><h3>暂无成员</h3><p>先在团队成员中添加在职员工；确认资源方案后，排期将自动更新。</p></div>
<p class="hint">单元格为该周占用合计（PLANNED + CONFIRMED），按周一为界划分；悬停查看占用明细。</p></section></template>

<template v-if="tab==='capability'"><section class="page-title"><div><span class="eyebrow">CAPABILITY INTELLIGENCE</span><h1>看清组织的能力边界。</h1><p>从项目需求出发，回答缺什么能力、靠谁支撑、谁不可替代。</p></div><select v-model.number="sdWeeks" @change="run(loadCapability)" aria-label="预测周期"><option :value="8">8 周</option><option :value="12">12 周</option><option :value="26">26 周</option></select></section><section class="panel"><div class="section-heading"><h2>技能供需缺口</h2><span v-if="supplyDemand" class="muted">{{supplyDemand.start}} → {{supplyDemand.end}} · {{supplyDemand.workdays}} 个工作日 · {{supplyDemand.summary.shortageSkills}}/{{supplyDemand.summary.skillsTracked}} 项技能存在缺口</span></div><div class="table-scroll"><table class="sd-table"><thead><tr><th>技能</th><th>要求</th><th>需求工时</th><th>达标人数</th><th>可供给工时</th><th>缺口</th><th>建议</th></tr></thead><tbody><tr v-for="r in supplyDemand?.rows||[]" :key="r.skillId" :class="{short:r.gapPeople>0}"><td>{{r.skillName}}</td><td>L{{r.requiredLevel}}</td><td>{{r.demandHours}} h / {{r.taskCount}} 任务</td><td>{{r.qualifiedCount}}</td><td>{{r.availableHours}} h</td><td>{{r.gapHours>0?r.gapHours+' h · 约 '+r.gapPeople+' 人':'—'}}</td><td>{{r.advice}}</td></tr></tbody></table></div><p v-if="supplyDemand&&!supplyDemand.rows.length" class="muted">预测窗口内暂无带技能需求的未完成任务。</p></section><section class="panel"><div class="section-heading"><h2>关键能力节点</h2><span class="muted">瓶颈技能 = 全公司达标人数 ≤ 2</span></div><div v-for="k in keyPeople" :key="k.employeeId" class="list-row"><span><b>{{k.employeeName}}</b><small class="cell-small">{{k.position}}</small></span><span class="tags"><span v-for="sk in k.keySkills" :key="sk.skillId" class="badge warning">{{sk.skillName}} L{{sk.requiredLevel}}（{{sk.qualifiedCount}} 人达标）</span></span><small>{{k.projectCount}} 个项目 · 已占用 {{k.loadedHours}} h</small></div><p v-if="!keyPeople.length" class="muted">暂无瓶颈技能持有人——当前技能达标面较宽。</p></section><section class="panel"><div class="section-heading"><h2>核心人员离开影响</h2><div class="actions"><select v-model="leavePick" aria-label="选择成员"><option value="" disabled>选择成员</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select><button class="secondary" :disabled="busy||!leavePick" @click="run(loadLeaveImpact)">评估影响</button></div></div><template v-if="leaveImpact"><p>{{leaveImpact.employeeName}}：12 周窗口内 {{leaveImpact.affectedTasks.length}} 个任务受影响，其中 {{leaveImpact.criticalTasks}} 个不可替代。</p><div v-for="t in leaveImpact.affectedTasks" :key="t.taskId" class="list-row"><span><b>{{t.projectName}} · {{t.taskName}}</b><small class="cell-small">{{t.startDate}} → {{t.endDate}} · {{t.hours}} h</small></span><small>{{t.replaceable?'有替代人选':'⚠ 无人可替代'}}<template v-for="n in t.needs" :key="n.skillName"> · {{n.skillName}}（{{n.otherQualified}} 人达标）</template></small></div><p v-if="!leaveImpact.affectedTasks.length" class="muted">该成员在 12 周窗口内没有生效分配。</p></template><p v-else class="muted">选择成员后评估其任务可替代性（what-if，不改变任何数据）。</p></section><section class="panel"><div class="section-heading"><h2>深入分析</h2><div class="actions"><button class="secondary" :disabled="busy||mode==='off'" @click="run(async()=>{await runAdvise()},'建议已生成')"><Sparkles :size="14"/>生成建议</button><button class="secondary" :disabled="busy" @click="run(async()=>{await runScenario()},'情景模拟完成')"><Compass :size="14"/>模拟待启动项目</button><button class="secondary" :disabled="busy" @click="run(async()=>{await runTrends()},'趋势已加载')"><CalendarRange :size="14"/>缺口趋势</button></div></div><p v-if="adviseText" class="review">{{adviseText}}</p><div v-if="scenario"><p><b>情景窗口 {{scenario.start}} → {{scenario.end}}（{{scenario.workdays}} 个工作日）</b>，纳入 {{scenario.includedProjects.length}} 个待启动项目：{{scenario.includedProjects.map((p:Row)=>p.name).join('、')}}</p><div v-if="scenario.rows.length" class="table-scroll"><table class="sd-table"><thead><tr><th>技能</th><th>当前缺口</th><th>情景缺口</th><th>增量</th></tr></thead><tbody><tr v-for="r in scenario.rows" :key="r.skillId" :class="{short:r.deltaPeople>0}"><td>{{r.skillName}}（L{{r.requiredLevel}}）</td><td>{{r.baseGapPeople}} 人</td><td>{{r.scenarioGapPeople}} 人</td><td>{{r.deltaPeople>0?'+':''}}{{r.deltaPeople}} 人</td></tr></tbody></table></div><p v-else class="muted">{{scenario.note||'情景叠加未产生新的能力缺口。'}}</p></div><div v-if="trends"><div v-if="trends.rows.length" class="table-scroll"><table class="trend-table"><thead><tr><th>技能</th><th>8 周</th><th>12 周</th><th>26 周</th></tr></thead><tbody><tr v-for="r in trends.rows" :key="r.skillId"><td>{{r.skillName}}（L{{r.requiredLevel}}）</td><td>{{r.w8}} 人</td><td>{{r.w12}} 人</td><td>{{r.w26}} 人</td></tr></tbody></table></div><p v-else class="muted">三档窗口（8/12/26 周）内均无技能缺口。</p></div><p v-if="!adviseText&&!scenario&&!trends" class="muted">生成 AI 建议（招聘 / 培训 / 外包 / 调配）、模拟待启动项目全部并行的放大效应，或查看三档窗口的缺口趋势。</p></section></template><template v-if="tab==='settings'"><section class="page-title"><div><span class="eyebrow">ORGANIZATION</span><h1>为协作打好基础。</h1><p>管理部门、技能分类与团队访问权限。</p></div></section><div class="two-columns"><section class="panel"><div class="section-heading"><h2>组织部门</h2><button v-if="canPeople" class="text-button" @click="editDepartment()">+ 新增部门</button></div><div v-for="d in departments" :key="d.id" class="list-row"><span>{{d.name}}</span><div class="actions" v-if="canPeople"><button class="icon-button" aria-label="编辑部门" @click="editDepartment(d)"><Pencil :size="14"/></button><button class="icon-button" aria-label="删除部门" @click="remove(`/departments/${d.id}`,refresh)">×</button></div></div></section><section class="panel"><div class="section-heading"><h2>技能分类</h2><button v-if="canPeople" class="text-button" @click="editCategory()">+ 新增分类</button></div><div v-for="c in categories" :key="c.id" class="list-row"><span>{{c.name}}</span><button v-if="canPeople" class="icon-button" aria-label="编辑分类" @click="editCategory(c)"><Pencil :size="14"/></button></div></section></div><section class="panel" v-if="admin"><div class="section-heading"><h2>账号与权限</h2><button class="secondary" @click="addAccount">+ 创建账号</button></div><p class="hint">管理员管理全部功能；项目经理维护项目和方案；部门经理维护人员和技能；员工只读。当前为组织级角色权限。</p><div class="table-scroll"><table><thead><tr><th>账号</th><th>角色</th><th>状态</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td>{{a.username}}</td><td>{{a.role}}</td><td>{{a.status}}</td></tr></tbody></table></div></section><section class="panel"><h2>规划模式</h2><p>{{mode==='demo'?'演示模式：使用固定模板验证流程，不调用大模型。':mode==='live'?'实时模式：通过配置的模型提供方生成规划与解释。':'AI 未启用：可以手动维护任务，人员匹配和求解正常可用。'}}</p><p class="muted">AI 只提供建议。正式资源分配始终需要项目负责人确认。</p></section><section class="panel"><h2>集成通知</h2><p v-if="notify">{{notify.mode==='live'?'已启用（'+notify.provider+'）：方案确认与重规划冲突事件将推送群机器人 webhook。':'未启用：设置 NOTIFY_MODE=live 与 NOTIFY_WEBHOOK_URL 后，方案确认与重规划冲突会推送到飞书 / 钉钉 / 企业微信 / 通用 webhook。'}}</p><p v-else class="muted">打开本页时加载通知配置。</p><div v-if="admin&&notifyLog.length" class="table-scroll"><table><thead><tr><th>事件</th><th>状态</th><th>耗时</th><th>时间</th></tr></thead><tbody><tr v-for="n in notifyLog" :key="n.id"><td>{{n.type}}</td><td>{{n.status}}</td><td>{{n.duration}} ms</td><td><small>{{n.created_at}}</small></td></tr></tbody></table></div></section></template>
</div><footer class="page-footer">序 · AI RESOURCE ORCHESTRATOR <span>让团队能力，成为项目的确定性。</span></footer></main>
<EditDialog v-if="dialog" :key="dialog.title" v-bind="dialog" @close="dialog=null"/>
</div>
</template>
